function ksParse(text){
  var items = [], lines = String(text||'').split(/\n/);
  for(var i=0;i<lines.length;i++){
    var s = lines[i].trim();
    if(!s) continue;
    var p = s.split(/[,\uFF0C]/).map(function(x){ return x.trim(); });
    if(p.length < 3) return { error: '第 ' + (i+1) + ' 行格式错误（需：名称,重量,价值）' };
    var wt = Number(p[1]), val = Number(p[2]);
    if(!isFinite(wt) || !isFinite(val) || wt <= 0 || val < 0) return { error: '第 ' + (i+1) + ' 行数值非法' };
    items.push({ name: p[0], w: wt, v: val });
  }
  if(!items.length) return { error: '至少需要一件物品' };
  return { items: items };
}
function ksSolve(items, cap){
  var n = items.length, W = Math.floor(cap);
  var dp = [];
  for(var i=0;i<=n;i++){ dp.push(new Array(W+1).fill(0)); }
  for(var i=1;i<=n;i++){
    var it = items[i-1];
    for(var w=0;w<=W;w++){
      dp[i][w] = dp[i-1][w];
      if(it.w <= w){
        var cand = dp[i-1][w - it.w] + it.v;
        if(cand > dp[i][w]) dp[i][w] = cand;
      }
    }
  }
  var picked = [], w = W;
  for(var i=n;i>=1;i--){
    if(dp[i][w] !== dp[i-1][w]){ picked.push(i-1); w -= items[i-1].w; }
  }
  picked.reverse();
  return { best: dp[n][W], dp: dp, picked: picked };
}
function ksGreedy(items, cap){
  var idx = items.map(function(_, i){ return i; });
  idx.sort(function(a, b){ return items[b].v/items[b].w - items[a].v/items[a].w || a - b; });
  var total = 0, wsum = 0, picked = [];
  for(var k=0;k<idx.length;k++){
    var it = items[idx[k]];
    if(wsum + it.w <= cap){ wsum += it.w; total += it.v; picked.push(idx[k]); }
  }
  return { best: total, picked: picked.sort(function(a,b){ return a-b; }) };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ksParse:ksParse, ksSolve:ksSolve, ksGreedy:ksGreedy };
}
if (typeof window !== 'undefined') {
  window.KnapsackForgePure = { ksParse:ksParse, ksSolve:ksSolve, ksGreedy:ksGreedy };
}
